const v31BaseFieldHtml = fieldHtml;
fieldHtml = function(field,value){
  if(field.type==='worker'){
    const opts=(state.v31Workers||[]).filter(r=>String(r.data?.status||'AKTIF').toUpperCase()!=='NONAKTIF');
    return `<label class="${field.cls||''}">${esc(field.label)}<select name="${field.name}" ${field.required?'required':''}><option value="">Pilih tukang</option>${opts.map(r=>`<option value="${esc(r.id)}" ${r.id===value?'selected':''}>${esc(r.data.name||'-')} — ${esc(r.data.workerType||r.data.skill1||r.data.skill||'')}</option>`).join('')}</select>${field.help?`<span class="field-help">${esc(field.help)}</span>`:''}</label>`;
  }
  if(field.type==='ati_issue'){
    const opts=state.v31AtiIssues||[];
    return `<label class="${field.cls||''}">${esc(field.label)}<select name="${field.name}" ${field.required?'required':''}><option value="">Pilih masalah</option>${opts.map(r=>`<option value="${esc(r.id)}" ${r.id===value?'selected':''}>${esc((r.data.problem||'-').slice(0,90))}</option>`).join('')}</select></label>`;
  }
  return v31BaseFieldHtml(field,value);
};

// Jangan tampilkan ID/kode proyek kepada user; hanya nama proyek.
projectName = function(id){return projectDisplayName(id);};
function v31Project(id){return state.projects.find(x=>x.id===id);}
