function v31WorkerName(id){const r=(state.v31Workers||[]).find(x=>x.id===id);return r?.data?.name||'-';}
function v31RoleEmployees(keys=[]){return state.employees.filter(e=>keys.includes(e.roleKey));}
function v31EmployeeOptions(keys=[],selected=''){return v31RoleEmployees(keys).map(e=>`<option value="${esc(e.id)}" ${e.id===selected?'selected':''}>${esc(e.name)} — ${esc(e.jabatan||e.role)}</option>`).join('');}
