/* ------------------------------ LAPORAN HARIAN + GAJI TUKANG ------------------------------ */
function v31WorkerAmount(status,dailyRate,otHours,otRate){const st=String(status||'HADIR').toUpperCase();const base=st==='HADIR'?num(dailyRate):st==='SETENGAH HARI'?num(dailyRate)*0.5:0;return base+num(otHours)*num(otRate);}
function v31WorkerRowHtml(w={}){const workers=(state.v31Workers||[]).filter(r=>String(r.data.status||'AKTIF').toUpperCase()!=='NONAKTIF');const selected=workers.find(x=>x.id===w.workerId);const daily=w.dailyRate??selected?.data.dailyRate??0;const otRate=w.overtimeRate??selected?.data.overtimeRate??0;const status=w.attendanceStatus||'HADIR';return `<div class="worker-row v31-grid-row"><select class="wr-worker" required><option value="">Pilih tukang</option>${workers.map(r=>`<option value="${esc(r.id)}" ${r.id===w.workerId?'selected':''}>${esc(r.data.name)} — ${esc(r.data.workerType||r.data.skill1||r.data.skill||'')}</option>`).join('')}</select><select class="wr-status"><option ${status==='HADIR'?'selected':''}>HADIR</option><option ${status==='SETENGAH HARI'?'selected':''}>SETENGAH HARI</option><option ${status==='IZIN'?'selected':''}>IZIN</option><option ${status==='SAKIT'?'selected':''}>SAKIT</option><option ${status==='ALPA'?'selected':''}>ALPA</option></select><input class="wr-rate" type="number" step="any" value="${esc(daily)}" placeholder="Upah harian"><input class="wr-ot-hours" type="number" step="any" min="0" value="${esc(w.overtimeHours||0)}" placeholder="Jam lembur"><input class="wr-ot-rate" type="number" step="any" value="${esc(otRate)}" placeholder="Tarif lembur"><input class="wr-total" value="${esc(v31WorkerAmount(status,daily,w.overtimeHours,otRate))}" readonly><button type="button" class="btn small danger wr-remove">×</button></div>`;}
function v31BindWorkerRows(){const box=$('#v31WorkerRows');if(!box)return;const recalc=row=>{const sel=$('.wr-worker',row);const worker=(state.v31Workers||[]).find(x=>x.id===sel.value);if(worker&&row.dataset.lastWorker!==sel.value){$('.wr-rate',row).value=num(worker.data.dailyRate);$('.wr-ot-rate',row).value=num(worker.data.overtimeRate);row.dataset.lastWorker=sel.value;}$('.wr-total',row).value=v31WorkerAmount($('.wr-status',row).value,$('.wr-rate',row).value,$('.wr-ot-hours',row).value,$('.wr-ot-rate',row).value);v31UpdatePayrollTotal();};$$('.worker-row',box).forEach(row=>{['change','input'].forEach(ev=>row.addEventListener(ev,()=>recalc(row)));$('.wr-remove',row).onclick=()=>{row.remove();v31UpdatePayrollTotal();};});}
function v31UpdatePayrollTotal(){const rows=$$('.worker-row','#v31WorkerRows');const total=rows.reduce((s,r)=>s+num($('.wr-total',r).value),0);if($('#v31WorkerCount'))$('#v31WorkerCount').textContent=rows.length;if($('#v31PayrollTotal'))$('#v31PayrollTotal').textContent=fmtRp(total);}
async function openDailyProgressForm(row=null){
  state.v31Workers=await loadCollection('tukang',false);const allWorkerRows=await loadCollection('daily_workers',false);const data=row?.data||{};let projectId=data.projectId||state.selectedProjectId||'';const workers=row?allWorkerRows.filter(x=>x.data.dailyProgressId===row.id).map(x=>x.data):[];const pid=v31AssignedPelaksana(projectId)||data.picUserId||'';
  const html=`<div class="form-grid"><label>Proyek<select name="projectId" id="v31DailyProject" required><option value="">Pilih proyek</option>${v31ProjectOptions(projectId)}</select></label><label>Tanggal<input name="date" type="date" value="${esc(data.date||new Date().toISOString().slice(0,10))}" required></label><label>Progress Aktual / Realisasi (%)<input name="progress" type="number" step="any" value="${esc(data.progress??'')}" required></label><label>Progress Rencana (%)<input name="planProgress" type="number" step="any" value="${esc(data.planProgress??'')}" required></label><label>PIC Laporan — Site Manager<input id="v31DailyPicName" value="${esc(employeeName(pid))}" readonly><input type="hidden" name="picUserId" id="v31DailyPic" value="${esc(pid)}"></label><label>Cuaca<input name="weather" value="${esc(data.weather||'')}"></label><label class="span-2">Pekerjaan Hari Ini<textarea name="work" required>${esc(data.work||'')}</textarea></label><label class="span-2">Kendala<textarea name="issue">${esc(data.issue||'')}</textarea></label><label class="span-2">Rencana Berikutnya<textarea name="nextPlan">${esc(data.nextPlan||'')}</textarea></label></div><div class="subsection"><div class="subsection-head"><div><h4>Tenaga Kerja Hari Ini</h4><p>Nama tukang dari Database Mitra — belum ada? klik + Tukang baru. Data ini otomatis menjadi rekap kehadiran dan upah.</p></div><button type="button" class="btn small primary" id="v31AddWorker">+ Tambah Tukang</button><button type="button" class="btn small" id="v31NewWorker">+ Tukang baru</button></div><div class="v31-worker-head"><span>Nama</span><span>Status</span><span>Upah Harian</span><span>Jam Lembur</span><span>Tarif Lembur</span><span>Total</span><span></span></div><div id="v31WorkerRows">${workers.map(v31WorkerRowHtml).join('')}</div><div class="payroll-total">Jumlah pekerja: <b id="v31WorkerCount">${workers.length}</b><span>Total upah hari ini: <b id="v31PayrollTotal">${fmtRp(workers.reduce((s,w)=>s+num(w.amount),0))}</b></span></div></div><label class="span-2">Lampiran progress (opsional)<input type="file" name="attachment"></label>`;
  openModal(row?'Edit Laporan Harian':'Tambah Laporan Harian','PIC dikunci ke Site Manager pada proyek. Kehadiran tukang langsung masuk Rekap Upah.',html,async form=>{
    const pId=form.projectId.value;const pelaksana=v31AssignedPelaksana(pId);if(!pelaksana)throw new Error('Proyek belum memiliki Site Manager. Isi penugasan proyek terlebih dahulu.');
    const wr=$$('.worker-row','#v31WorkerRows');const seen=new Set();const attendance=wr.map(r=>{const workerId=$('.wr-worker',r).value;if(!workerId)throw new Error('Pilih nama tukang pada semua baris.');if(seen.has(workerId))throw new Error('Nama tukang tidak boleh ganda pada laporan harian yang sama.');seen.add(workerId);const st=$('.wr-status',r).value;const rate=num($('.wr-rate',r).value);const oth=num($('.wr-ot-hours',r).value);const otr=num($('.wr-ot-rate',r).value);return {workerId,workerName:v31WorkerName(workerId),attendanceStatus:st,dailyRate:rate,overtimeHours:oth,overtimeRate:otr,amount:v31WorkerAmount(st,rate,oth,otr)};});
    const payload={projectId:pId,date:form.date.value,progress:num(form.progress.value),planProgress:num(form.planProgress.value),picUserId:pelaksana,manpower:attendance.filter(x=>!['ALPA','IZIN','SAKIT'].includes(x.attendanceStatus)).length,weather:form.weather.value,work:form.work.value,issue:form.issue.value,nextPlan:form.nextPlan.value};const id=row?.id||crypto.randomUUID();
    if(row)await api(`/api/records/daily_progress/${encodeURIComponent(id)}`,{method:'PUT',body:payload});else await api('/api/records/daily_progress',{method:'POST',body:{id,data:payload}});
    const old=allWorkerRows.filter(x=>x.data.dailyProgressId===id);for(const x of old)await api(`/api/records/daily_workers/${encodeURIComponent(x.id)}`,{method:'DELETE'});
    for(const a of attendance)await api('/api/records/daily_workers',{method:'POST',body:{id:crypto.randomUUID(),data:{...a,projectId:pId,dailyProgressId:id,date:payload.date,picUserId:pelaksana,status:'RECORDED'}}});
    const file=form.attachment.files?.[0];if(file)await uploadRelatedDocument(file,{projectId:pId,category:'OTHER',title:`Laporan Harian ${projectName(pId)} - ${payload.date}`,relatedCollection:'daily_progress',relatedId:id});toast('Laporan harian dan rekap upah tukang tersimpan.');await refreshAfterMutation();
  });
  $('#v31DailyProject').onchange=()=>{const id=$('#v31DailyProject').value;const pic=v31AssignedPelaksana(id);$('#v31DailyPic').value=pic;$('#v31DailyPicName').value=employeeName(pic);};
  $('#v31AddWorker').onclick=()=>{if(!(state.v31Workers||[]).length){toast('Belum ada data tukang. Klik "+ Tukang baru" untuk menambahkan.','err');return;}$('#v31WorkerRows').insertAdjacentHTML('beforeend',v31WorkerRowHtml({}));v31BindWorkerRows();v31UpdatePayrollTotal();};v31BindWorkerRows();v31UpdatePayrollTotal();
}

renderProgress = async function(){
  const scope=Boolean(state.selectedProjectId);state.v31Workers=await loadCollection('tukang',false);const [daily,dailyWorkers,weekly,schedule,milestones,issues]=await Promise.all([loadCollection('daily_progress',scope),loadCollection('daily_workers',scope),loadCollection('weekly_progress',scope),loadCollection('schedule',scope),loadCollection('milestones',scope),loadCollection('issues',scope)]);
  const payrollTotal=dailyWorkers.reduce((s,r)=>s+num(r.data.amount),0);const dailyTable=`<div class="card"><div class="card-head"><div><h3>Laporan Harian Lapangan</h3><p>PIC selalu Site Manager. Nama tukang di laporan ini otomatis masuk rekap gaji.</p></div>${canCollection('daily_progress','create')?'<div class="card-actions"><button class="btn primary" id="v31AddDaily">+ Laporan Harian</button></div>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Site Manager</th><th>Pekerjaan</th><th>Aktual</th><th>Rencana</th><th>Tukang</th><th>Status</th><th></th></tr></thead><tbody>${v3418Visible(daily).map(r=>{const cnt=dailyWorkers.filter(x=>x.data.dailyProgressId===r.id).length;return `<tr><td>${fmtDate(r.data.date)}</td><td><b>${esc(projectName(r.data.projectId))}</b></td><td>${esc(employeeName(r.data.picUserId))}</td><td>${esc(r.data.work||'-')}</td><td>${fmtNum(r.data.progress)}%</td><td>${fmtNum(r.data.planProgress)}%</td><td>${cnt}</td><td>${progressStatusPill(r.data.status)}</td><td class="actions">${v34WorkflowButtons('daily_progress',r)}${canCollection('daily_progress','update')&&['DRAFT','RETURNED_TO_FIELD',''].includes(String(r.data.status||'').toUpperCase())?`<button class="btn small" data-daily-edit="${esc(r.id)}">Edit</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty">Belum ada laporan harian.</td></tr>'}${v3418MoreNote(daily,9)}</tbody></table></div></div>`;
  const wage=`<div class="card"><div class="card-head"><div><h3>Rekap Kehadiran & Gaji Tukang</h3><p>Terbentuk otomatis dari daftar tukang pada laporan harian.</p></div><div class="pill green">Total ${fmtRp(payrollTotal)}</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Nama Tukang</th><th>Status</th><th>Upah Harian</th><th>Lembur</th><th>Total</th></tr></thead><tbody>${dailyWorkers.sort((a,b)=>String(b.data.date||'').localeCompare(String(a.data.date||''))).slice(0,V3418_MAX_ROWS).map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${esc(projectName(r.data.projectId))}</td><td><b>${esc(r.data.workerName||v31WorkerName(r.data.workerId))}</b></td><td>${statusPill(r.data.attendanceStatus)}</td><td class="num">${fmtRp(r.data.dailyRate)}</td><td>${fmtNum(r.data.overtimeHours)} jam × ${fmtRp(r.data.overtimeRate)}</td><td class="num"><b>${fmtRp(r.data.amount)}</b></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Belum ada rekap upah.</td></tr>'}${v3418MoreNote(dailyWorkers,7)}</tbody></table></div></div>`;
  $('#content').innerHTML=`<div class="notice green">Grafik Dashboard tetap memakai Progress Rencana dan Aktual/Realisasi. Laporan harian sekarang juga menjadi sumber absensi/upah tukang.</div>${dailyTable}${wage}${genericTable('weekly_progress',weekly,'Progress Mingguan','PIC dibatasi Site Manager.')}${genericTable('schedule',schedule,'Schedule / Kurva-S','PIC pelaksanaan dibatasi Site Manager.')}${genericTable('milestones',milestones,'Milestone','Target penting proyek.')}${genericTable('issues',issues,'Masalah & Corrective Action','PIC tindak lanjut lapangan dibatasi Site Manager.')}`;bindCrudActions();if($('#v31AddDaily'))$('#v31AddDaily').onclick=()=>openDailyProgressForm();$$('[data-daily-edit]').forEach(b=>b.onclick=()=>openDailyProgressForm(daily.find(x=>x.id===b.dataset.dailyEdit)));
};

