function normalizePositionLabel(value){
  const raw=String(value||'').trim();
  const key=raw.toLowerCase().replace(/[._-]+/g,' ').replace(/\s+/g,' ');
  const map={
    'head operational':'Head of Operational','head operasional':'Head of Operational','manager operasional':'Head of Operational','manajer operasional':'Head of Operational',
    'koordinator engineering':'Head of Engineering','head engineering':'Head of Engineering',
    'koordinator supporting':'Head of Supporting','head supporting':'Head of Supporting',
    'quality control':'QC','qc / quality control':'QC','qc':'QC','senior qc':'QC','qc arsitektur':'QC','qc interior':'QC','qc mep':'QC',
    'site manager':'Site Manager','sm':'Site Manager','superintendent':'Site Manager','site superintendent':'Site Manager','superindtent':'Site Manager',
    'project manager':'Site Manager','pm':'Site Manager','pelaksana lapangan':'Site Manager','pelaksana':'Site Manager',
    'pengawas':'Site Manager','pengawas lapangan':'Site Manager','site supervisor':'Site Manager',
    'logistik':'Admin Logistik','manager logistik':'Admin Logistik','staf logistik':'Admin Logistik','staff logistik':'Admin Logistik','procurement':'Admin Logistik','admin logistik':'Admin Logistik'
  };
  return map[key]||raw;
}

