function v33BindReportActions(type,reports){
  $$(`[data-report-create="${type}"]`).forEach(b=>b.onclick=()=>v33ComposeReport(type,b.dataset.period));
  $$(`[data-report-detail="${type}"]`).forEach(b=>b.onclick=()=>v33OpenReportDetail(type,reports.find(x=>x.id===b.dataset.id)));
  $$(`[data-report-edit="${type}"]`).forEach(b=>b.onclick=()=>v349EditDivisionReport(type,reports.find(x=>x.id===b.dataset.id)));
  $$(`[data-report-delete="${type}"]`).forEach(b=>b.onclick=()=>v349DeleteDivisionReport(type,reports.find(x=>x.id===b.dataset.id)));
  $$(`[data-report-review="${type}"]`).forEach(b=>b.onclick=async()=>{await api(`/api/reports/${type.toLowerCase()}/${encodeURIComponent(b.dataset.id)}/review`,{method:'POST'});toast('Laporan ditandai sudah direview oleh Head Unit Bisnis.');state.cache.clear();await renderView();});
}
function v33ComposeReport(type,periodType){
  // V3.4.23: periode laporan bisa dipilih dari tanggal … sampai tanggal …
  const today=new Date(Date.now()+8*36e5).toISOString().slice(0,10);const [s0,e0]=v3423Range(periodType,today);
  const opt=(v,l)=>`<option value="${v}" ${v===periodType?'selected':''}>${l}</option>`;
  const html=`<div class="form-grid"><label>Jenis Laporan<select name="periodType">${opt('WEEKLY','Mingguan (Senin–Minggu)')}${opt('MONTHLY','Bulanan (tgl 1–akhir bulan)')}${opt('CUSTOM','Periode khusus (pilih sendiri)')}</select></label><div class="report-range-quick"><span>Pilih cepat</span><button type="button" class="btn small" data-range="thisweek">Minggu ini</button><button type="button" class="btn small" data-range="lastweek">Minggu lalu</button><button type="button" class="btn small" data-range="thismonth">Bulan ini</button><button type="button" class="btn small" data-range="lastmonth">Bulan lalu</button></div><label>Dari tanggal<input type="date" name="startDate" value="${s0}" max="${today}" required></label><label>Sampai tanggal<input type="date" name="endDate" value="${e0}" required><span class="field-help" id="reportRangeInfo"></span></label>${type==='QC'?v3427QcComposeFields():''}<label class="span-2">Catatan Pengantar ke Head Unit Bisnis<textarea name="notes" placeholder="Contoh: fokus temuan mayor periode ini, kebutuhan keputusan, atau catatan khusus."></textarea></label></div><div class="notice blue"><b>Otomatis dari data Nara System.</b> Laporan tidak diisi ulang manual. Snapshot dibuat dari data dashboard ${type} pada periode yang dipilih lalu langsung dikirim ke akun Head Unit Bisnis.</div>`;
  openModal(`Buat & Kirim Laporan ${type}`,'Penerima otomatis: seluruh akun aktif dengan posisi Head Unit Bisnis.',html,async form=>{
    const a=form.startDate.value,b=form.endDate.value;if(!a||!b)throw new Error('Isi tanggal awal dan akhir periode.');if(b<a)throw new Error('Tanggal akhir tidak boleh sebelum tanggal awal.');
    const r=await api(`/api/reports/${type.toLowerCase()}/generate`,{method:'POST',body:{periodType:form.periodType.value,startDate:a,endDate:b,notes:form.notes.value,reportKind:form.reportKind?.value,projectId:form.scopeProjectId?.value||'',withPhotos:form.withPhotos?form.withPhotos.checked:undefined}});
    toast(`${r.row?.data?.title||`Laporan ${type}`} berhasil dikirim ke Head Unit Bisnis dan tersimpan di arsip.`);state.cache.clear();await renderView();
  });$('#modalSave').textContent='Buat & Kirim';
  const f=$('#modalForm'),sel=f.periodType,st=f.startDate,en=f.endDate,info=$('#reportRangeInfo');
  const refresh=()=>{const a=st.value,b=en.value;en.min=a||'';if(a&&b){const n=Math.round((Date.parse(b)-Date.parse(a))/864e5)+1;info.textContent=n>0?`${n} hari · ${fmtDate(a)} – ${fmtDate(b)}`:'Tanggal akhir sebelum tanggal awal.';info.style.color=n>0?'':'var(--danger)';}else info.textContent='';};
  const setRange=(a,b)=>{st.value=a;en.value=b;refresh();};
  sel.onchange=()=>{if(sel.value!=='CUSTOM'){const [a,b]=v3423Range(sel.value,st.value||today);setRange(a,b);}else refresh();};
  const manual=()=>{const t=sel.value;if(t!=='CUSTOM'){const [a,b]=v3423Range(t,st.value);if(a!==st.value||b!==en.value)sel.value='CUSTOM';}refresh();};
  st.onchange=manual;en.onchange=manual;
  $$('[data-range]',f).forEach(btn=>btn.onclick=()=>{const k=btn.dataset.range;const base=new Date(today+'T12:00:00Z');if(k==='thisweek'){sel.value='WEEKLY';const [a,b]=v3423Range('WEEKLY',today);setRange(a,b);}if(k==='lastweek'){sel.value='WEEKLY';base.setUTCDate(base.getUTCDate()-7);const [a,b]=v3423Range('WEEKLY',base.toISOString().slice(0,10));setRange(a,b);}if(k==='thismonth'){sel.value='MONTHLY';const [a,b]=v3423Range('MONTHLY',today);setRange(a,b);}if(k==='lastmonth'){sel.value='MONTHLY';base.setUTCDate(0);const [a,b]=v3423Range('MONTHLY',base.toISOString().slice(0,10));setRange(a,b);}});
  refresh();
}
function v33RowsTable(headers,rows,empty='Tidak ada data pada periode ini.'){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">${esc(empty)}</td></tr>`}</tbody></table></div>`;}
function v33OpenReportDetail(type,row){if(!row)return;const d=row.data||{},s=d.snapshot||{},m=s.metrics||{};let body='';
  if(type==='QC'){
    const groups=(s.groups||[]).map(x=>`<tr><td>${esc(x.workGroup)}</td><td>${fmtNum(x.total,0)}</td><td>${fmtNum(x.sesuai,0)}</td><td>${fmtNum(x.tidak,0)}</td><td>${x.total?Math.round(num(x.sesuai)/num(x.total)*100):0}%</td></tr>`).join('');
    const inspections=(s.inspections||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.workGroup)}</td><td>${esc(x.item)}</td><td>${statusPill(x.result)}</td><td>${esc(x.inspector)}</td><td>${esc(x.note||'-')}</td></tr>`).join('');
    const findings=(s.findings||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.area)}</td><td>${esc(x.description)}</td><td>${statusPill(x.severity)}</td><td>${esc(x.pic)}</td><td>${fmtDate(x.deadline)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    body=`<div class="kpis report-kpis">${kpi('Catatan Inspeksi',m.catatanInspeksi||0,'blue')}${kpi('Sub-pekerjaan',m.subPekerjaan||0,'purple')}${kpi('Sesuai',m.sesuai||0,'green')}${kpi('Tidak Sesuai',m.tidakSesuai||0,'red')}${kpi('Kesesuaian',`${m.kesesuaian||0}%`,'orange')}${kpi('Total Temuan',m.totalTemuan||0,'orange')}${kpi('Open / Perbaikan',m.openPerbaikan||0,'red')}${kpi('Menunggu Verifikasi',m.menungguVerifikasi||0,'purple')}${kpi('Closed On Time',m.closedOnTime||0,'green')}${kpi('Overdue',m.overdue||0,'red')}${kpi('QC Score',`${m.qcScore??100}%`,'blue')}</div><h4>Rekap per Item Pekerjaan</h4>${v33RowsTable(['Item Pekerjaan','Sub','Sesuai','Tidak','Kesesuaian'],groups)}<h4>Rincian Pemeriksaan</h4>${v33RowsTable(['Tanggal','Proyek','Kelompok','Sub-pekerjaan','Hasil','Pemeriksa','Keterangan'],inspections)}<h4>Temuan QC Periode</h4>${v33RowsTable(['Tanggal','Proyek','Area','Temuan','Severity','PIC','Deadline','Status'],findings)}`;
  }else{
    const top=(s.top||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.name)}</td><td>${esc(x.skill)}</td><td>${esc(x.level)}</td><td><b>${fmtNum(x.score,1)}</b></td></tr>`).join('');
    const levels=(s.levels||[]).map(x=>`<tr><td><b>${esc(x.level)}</b></td><td>${esc(v31AtiLevelLabel(x.level))}</td><td>${fmtNum(x.count,0)}</td></tr>`).join('');
    const requests=(s.requests||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.workPackage)}</td><td>${fmtNum(x.requiredWorkers,0)}</td><td>${esc(x.requiredSkill)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    const attendance=(s.attendance||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.worker)}</td><td>${statusPill(x.status)}</td><td>${fmtRp(x.dailyRate)}</td><td>${fmtNum(x.overtimeHours)} jam</td><td>${fmtRp(x.amount)}</td></tr>`).join('');
    const issues=(s.issues||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.problem)}</td><td>${esc(x.pic)}</td><td>${fmtDate(x.deadline)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    const evaluations=(s.evaluations||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.issueId||'-')}</td><td>${esc(x.evaluator)}</td><td>${esc(x.rootCause)}</td><td>${esc(x.resolution)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    const assessments=(s.assessments||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(v31WorkerName(x.workerId)||x.workerId||'-')}</td><td>${esc(x.project)}</td><td>${esc(x.assessor)}</td><td><b>${fmtNum(x.score,1)}</b></td><td>${esc(x.notes||'-')}</td></tr>`).join('');
    const trainings=(s.training||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(v31WorkerName(x.workerId)||x.workerId||'-')}</td><td>${esc(x.name)}</td><td>${esc(x.trainer)}</td><td>${esc(x.result)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    body=`<div class="kpis report-kpis">${kpi('Total Database',m.totalDatabase||0,'blue')}${kpi('Aktif',m.aktif||0,'green')}${kpi('Available',m.available||0,'green')}${kpi('Hadir Periode',m.hadirPeriode||0,'purple')}${kpi('Masuk Periode',m.masukPeriode||0,'blue')}${kpi('Keluar Periode',m.keluarPeriode||0,'red')}${kpi('Total Upah',fmtRp(m.totalUpah||0),'purple')}${kpi('Avg. Performance',fmtNum(m.avgPerformance||0,1),'orange')}</div><div class="grid g-2"><div><h4>Top 10 Tukang</h4>${v33RowsTable(['#','Nama','Skill','Level','Skor'],top)}</div><div><h4>Leveling ATI</h4>${v33RowsTable(['Level','Jenjang','Jumlah'],levels)}</div></div><h4>Pengajuan Pekerjaan</h4>${v33RowsTable(['Tanggal','Proyek','Work Package','Jumlah','Skill','Status'],requests)}<h4>Attendance & Productivity / Rekap Upah</h4>${v33RowsTable(['Tanggal','Proyek','Tukang','Status','Upah','Lembur','Total'],attendance)}<h4>Masalah Lapangan</h4>${v33RowsTable(['Tanggal','Proyek','Masalah','PIC','Deadline','Status'],issues)}<h4>Evaluasi Masalah</h4>${v33RowsTable(['Tanggal','ID Masalah','Evaluator','Akar Masalah','Solusi','Status'],evaluations)}<h4>Assessment / Grading</h4>${v33RowsTable(['Tanggal','Tukang','Proyek','Penilai','Skor','Catatan'],assessments)}<h4>Pelatihan</h4>${v33RowsTable(['Tanggal','Peserta','Pelatihan','Instruktur','Hasil','Status'],trainings)}`;
  }
  v3427MarkRead(type,row);openModal(d.title||`Laporan ${type}`,`${v33ReportPeriodLabel(d)}${d.projectName?` • ${d.projectName}`:' • Semua proyek'} • Dikirim ke ${d.recipientRole||'Head Unit Bisnis'}`,`<div class="report-detail">${d.notes?`<div class="notice blue"><b>Catatan pengantar:</b> ${esc(d.notes)}</div>`:''}${body}</div>`,async()=>{});$('#modalSave').textContent='Tutup';$('#modalCancel').classList.add('hidden');$('.modal')?.classList.add('report-modal');
}

