function asBuiltPct(v){return Math.max(0,Math.min(100,num(v)));}
function asBuiltOverall(d={}){return Math.round((asBuiltPct(d.architectureProgress)+asBuiltPct(d.structureProgress)+asBuiltPct(d.mepProgress))/3);}
function asBuiltBar(v){const p=asBuiltPct(v);return `<div class="asbuilt-meter"><i style="width:${p}%"></i><span>${fmtNum(p)}%</span></div>`;}
function asBuiltDocLink(id,label){return id?`<a class="btn small" target="_blank" href="/api/documents/${encodeURIComponent(id)}/file">Buka ${esc(label)}</a>`:`<span class="pill gray">Belum ada ${esc(label)}</span>`;}
function asBuiltCanEditRow(row){const status=String(row?.data?.status||'NOT STARTED').toUpperCase();if(['READY FOR APPROVAL','APPROVED'].includes(status)&&state.access?.roleKey==='drafter')return false;return canCollection('as_built_progress',row?'update':'create');}
function asBuiltActionButtons(row,projectId){
  const pd=state.projects.find(p=>String(p.id)===String(projectId))?.data||{};if(!pd.drafterUserId)return '<span class="pill orange">Tetapkan Drafter</span>';
  if(!row)return asBuiltCanEditRow(null)?`<button class="btn small primary" data-asbuilt-edit="" data-project-id="${esc(projectId)}">Mulai / Update</button>`:'-';
  const d=row.data||{},s=String(d.status||'NOT STARTED').toUpperCase();let x=`<button class="btn small" data-asbuilt-detail="${esc(row.id)}">Detail</button>`;
  if(asBuiltCanEditRow(row)&&!['APPROVED'].includes(s))x+=`<button class="btn small" data-asbuilt-edit="${esc(row.id)}" data-project-id="${esc(projectId)}">Update / Upload</button>`;
  const complete=asBuiltPct(d.architectureProgress)>=100&&asBuiltPct(d.structureProgress)>=100&&asBuiltPct(d.mepProgress)>=100&&d.architectureDocId&&d.structureDocId&&d.mepDocId;
  const role=state.access?.roleKey;
  if(complete&&['NOT STARTED','IN PROGRESS','REVISION REQUIRED','DRAFT'].includes(s)&&['drafter','koordinator_engineering','admin_teknik','manager_operasional','head_unit_bisnis','administrator','direktur'].includes(role))x+=`<button class="btn small primary" data-asbuilt-action="submit" data-id="${esc(row.id)}">Kirim Approval</button>`;
  if(s==='READY FOR APPROVAL'&&cap('asBuiltApprove'))x+=`<button class="btn small success" data-asbuilt-action="approve" data-id="${esc(row.id)}">Approve</button><button class="btn small danger" data-asbuilt-action="return" data-id="${esc(row.id)}">Revisi</button>`;
  return x;
}
function asBuiltProjects(){
  const role=state.access?.roleKey;
  let rows=state.projects||[];
  if(role==='drafter')rows=rows.filter(p=>String(p.data?.drafterUserId||'')===String(state.user?.id||''));
  if(state.selectedProjectId)rows=rows.filter(p=>String(p.id)===String(state.selectedProjectId));
  return rows;
}
