let v3418BadgeTimer=null,v3418BadgeInflight=false;
async function v3418LoadTaskBadge(){
  const badge=$('#taskBadge');if(!badge||!canView('tasks'))return;
  if(v3418BadgeInflight)return;v3418BadgeInflight=true;
  try{const r=await api('/api/tasks/count');const n=num(r.count);badge.textContent=n;badge.classList.toggle('hidden',!n);}catch{badge.classList.add('hidden');}
  finally{v3418BadgeInflight=false;}
}
