/* V3.4.18 — Pemuatan data aman & efisien:
   - koleksi yang tidak boleh dibaca role aktif dikembalikan kosong (halaman tidak error total);
   - permintaan identik yang berjalan bersamaan digabung menjadi satu request. */
const v3418BaseLoadCollection=loadCollection;const v3418Inflight=new Map();
loadCollection=async function(c,projectScoped=false){
  const perm=state.access?.collections?.[c];if(perm&&!perm.read)return [];
  const key=`${c}|${projectScoped?state.selectedProjectId:''}`;if(state.cache.has(key))return state.cache.get(key);
  if(v3418Inflight.has(key))return v3418Inflight.get(key);
  const pr=v3418BaseLoadCollection(c,projectScoped).finally(()=>v3418Inflight.delete(key));v3418Inflight.set(key,pr);return pr;
};

