const EMAIL_STATUS_LABEL={SENT:['Terkirim','green'],PENDING:['Antre','orange'],SENDING:['Mengirim','orange'],FAILED:['Gagal','red'],NOT_CONFIGURED:['Belum dikonfigurasi','gray']};
function emailTime(v){const d=new Date(v);return Number.isNaN(d.getTime())?'-':new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(d);}
function emailStatusPill(s){const m=EMAIL_STATUS_LABEL[String(s||'').toUpperCase()]||[s||'-','gray'];return `<span class="pill ${m[1]}">${esc(m[0])}</span>`;}
function emailNotificationCardHtml(d){
  const c=d.config||{},n=d.counts||{};const prov={gas:'Google Apps Script (Gmail)',brevo:'Brevo',resend:'Resend'}[c.provider]||'Belum dipilih';
  const cfgNote=c.ready?`<div class="notice green"><b>Aktif via ${esc(prov)}.</b> Pengirim: ${esc(c.fromName||'')}${c.from&&c.provider!=='gas'?` &lt;${esc(c.from)}&gt;`:''}. Link di email: ${esc(c.baseUrl||'-')}</div>`:`<div class="notice"><b>Notifikasi email belum aktif.</b> Lengkapi konfigurasi di Cloudflare: ${esc((c.missing||[]).join(', '))}. Tugas tetap tercatat; email yang tertahan bisa dikirim ulang setelah konfigurasi selesai. Panduan ada di file EMAIL-SETUP.md.</div>`;
  const noEmail=(d.usersWithoutEmail||[]);
  const rows=(d.recent||[]).map(r=>`<tr><td>${emailTime(r.sentAt||r.createdAt||r.updated_at)}</td><td><b>${esc(r.toName||'-')}</b><div class="tiny muted">${esc(r.to||'')}</div></td><td>${esc(r.subject||'-')}</td><td>${emailStatusPill(r.status)}${r.lastError?`<div class="tiny muted" style="max-width:260px;white-space:normal">${esc(r.lastError)}</div>`:''}</td><td class="num">${fmtNum(r.attempts,0)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Belum ada email notifikasi.</td></tr>';
  return `<div class="card" id="emailNotifCard" style="margin-top:16px"><div class="card-head"><div><h3>Notifikasi Email Tugas</h3><p>Setiap tugas baru di Tugas Saya dikirim ke email penerimanya. Gagal kirim dicoba ulang otomatis setiap 5 menit.</p></div><div class="card-actions"><button class="btn" id="emailRetry" type="button">Kirim Ulang yang Gagal</button><button class="btn primary" id="emailTest" type="button">Kirim Email Uji</button></div></div><div class="card-body">${cfgNote}<div class="kpis">${kpi('Terkirim',fmtNum(n.SENT||0,0),'green')}${kpi('Antre',fmtNum((n.PENDING||0)+(n.SENDING||0),0),'orange')}${kpi('Gagal',fmtNum(n.FAILED||0,0),'red')}${kpi('Tertahan',fmtNum(n.NOT_CONFIGURED||0,0),'')}</div>${noEmail.length?`<div class="notice"><b>${noEmail.length} karyawan aktif belum punya email</b> sehingga tidak menerima notifikasi: ${esc(noEmail.slice(0,15).join(', '))}${noEmail.length>15?' …':''}</div>`:''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>Penerima</th><th>Subjek</th><th>Status</th><th>Percobaan</th></tr></thead><tbody>${rows}</tbody></table></div></div>`;
}
async function renderEmailNotificationCard(){
  if(!cap('manageEmployees'))return;
  let d;try{d=await api('/api/notifications/email');}catch(e){$('#content').insertAdjacentHTML('beforeend',`<div class="notice">Status notifikasi email gagal dimuat: ${esc(e.message)}</div>`);return;}
  $('#emailNotifCard')?.remove();$('#content').insertAdjacentHTML('beforeend',emailNotificationCardHtml(d));
  $('#emailTest').onclick=()=>openModal('Kirim Email Uji','Memastikan konfigurasi pengiriman email berfungsi.',`<label>Email tujuan<input type="email" name="to" value="${esc(state.user?.email||'')}" required></label>`,async form=>{const r=await api('/api/notifications/email/test',{method:'POST',body:{to:form.to.value}});toast(r.message);});
  $('#emailRetry').onclick=async()=>{try{const r=await api('/api/notifications/email/retry',{method:'POST'});toast(`Dikirim ulang: ${r.sent||0} terkirim, ${r.failed||0} gagal${r.skipped?' (email belum dikonfigurasi)':''}.`);await renderEmailNotificationCard();}catch(e){toast(e.message,'err');}};
}
