  $$('[data-term-edit]').forEach(b=>b.onclick=()=>openTermForm(find(b.dataset.termEdit)));
  $$('[data-term-del]').forEach(b=>b.onclick=async()=>{if(!confirmInline(b))return;await api(`/api/records/project_terms/${encodeURIComponent(b.dataset.termDel)}`,{method:'DELETE'});toast('Termin dihapus.');state.cache.clear();renderView();});
