  const groups=new Map();for(const r of rows){const k=dirKey(r.name).split(' ').slice(0,2).join(' ');if(!k)continue;groups.set(k,[...(groups.get(k)||[]),r]);}
  const suggest=[...groups.values()].filter(g=>g.length>1).slice(0,6);
  const nominal=r=>type==='TUKANG'?`${fmtNum(r.days,1)} hari · ${fmtRp(r.earned)}`:type==='SUPPLIER'?fmtRp(r.totals.purchased):fmtRp(r.totals.value);
