  $('#content').innerHTML=`<div class="kpis">${kpi('Total laporan',fmtNum(reports.length,0),'blue')}${kpi('Belum dibaca Head Unit Bisnis',fmtNum(unread,0),unread?'orange':'green')}${kpi('Rata-rata nilai',vals.length?`${Math.round(vals.reduce((a,b)=>a+b,0)/vals.length)}%`:'-','purple')}${kpi('Laporan bulan ini',fmtNum(reports.filter(r=>String(r.data.submittedAt||'').slice(0,7)===finToday().slice(0,7)).length,0),'')}</div>
  <div class="card"><div class="card-head"><div><h3>Arsip Laporan</h3><p>Laporan yang pernah dikirim ke Head Unit Bisnis. Isi laporan adalah snapshot saat dikirim, jadi tidak berubah walau data QC berubah setelahnya.</p></div><div class="card-actions">${canCreate?'<button class="btn" data-arch-new="TEMUAN">+ Laporan Temuan</button><button class="btn primary" data-arch-new="INSPEKSI">+ Laporan Inspeksi</button>':''}<button class="btn" id="archReload">Muat ulang</button></div></div>
  <div class="arch-toolbar"><input type="search" id="archQ" placeholder="Cari judul, pengirim, proyek…" value="${esc(f.q)}"><select id="archKind"><option value="">Semua jenis</option><option value="INSPEKSI">Inspeksi</option><option value="TEMUAN">Temuan</option><option value="GABUNGAN">Inspeksi + Temuan (lama)</option></select><select id="archMonth"><option value="">Semua bulan</option>${months.map(m=>`<option value="${m}">${new Date(m+'-15T00:00:00Z').toLocaleDateString('id-ID',{month:'long',year:'numeric'})}</option>`).join('')}</select><select id="archRead"><option value="">Semua status</option><option value="unread">Belum dibaca</option><option value="read">Dibaca</option></select></div>
  <div id="archTable"></div></div>`;
