  const kpis=(k==='TEMUAN'?[['Total temuan',m.totalTemuan],['Selesai',m.temuanSelesai??'-'],['Masih terbuka',m.openPerbaikan],['Menunggu verifikasi',m.menungguVerifikasi],['Tepat waktu',m.closedOnTime],['Lewat deadline',m.overdue],['QC Score',`${m.qcScore??100}%`]]:[['Catatan inspeksi',m.catatanInspeksi],['Sub-pekerjaan',m.subPekerjaan],['Sesuai',m.sesuai],['Tidak sesuai',m.tidakSesuai],['Butuh konfirmasi',m.butuhKonfirmasi||0],['Kesesuaian',`${m.kesesuaian||0}%`],['Temuan baru',m.totalTemuan]]).map(([l,v])=>`<div class="k"><span>${e(l)}</span><b>${e(v??0)}</b></div>`).join('');
